KAPITEL = [("1", "Grundlagen"), ("2", "Tod & Obduktion"), ("3", "Krankheitslehre"), ("4", "Zellpathologie"),
           ("5", "Entzündung & Wundheilung"), ("6", "Tumorpathologie"), ("7", "Kreislaufstörungen"), ("8", "Stoffwechsel & Gefäße")]

fragen = [{"id": f"patbud-{i:03d}", "kapitel": k, "typ": "kurz", "frage": frage, "antwortKurz": antwort,
           "erklaerung": f"{hinweis} Punkte im WS24-Bogen: {punkte}.", "seite": seite, "prio": "hoch"}
          for i, (k, seite, punkte, frage, antwort, hinweis) in enumerate(FRAGEN, 1)]

assert {f["kapitel"] for f in fragen} == {k for k, _ in KAPITEL}
assert len({f["frage"] for f in fragen}) == len(fragen)
ziel.mkdir(exist_ok=True)
(ziel / "fragen.json").write_text("[\n" + ",\n".join(json.dumps(f, ensure_ascii=False) for f in fragen) + "\n]\n", encoding="utf-8")
meta = {"id": "patho-buddy", "titel": "Pathologie – Buddyfragen", "kurz": "PATHO-BUDDY", "datum": "2026-11-30", "aktiv": True,
        "form": "Offene Fragen aus den Buddy-Bögen (Fragenkatalog + WS24), Antworten zusammengeführt und mit dem Skript geprüft",
        "kapitel": [{"nr": k, "titel": t} for k, t in KAPITEL],
        "gruppen": [{"nr": k, "titel": t, "thema": "", "praefix": [k]} for k, t in KAPITEL]}
(ziel / "meta.json").write_text(json.dumps(meta, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(len(fragen), "Buddyfragen geschrieben;", sum(GLEICH not in f["erklaerung"] for f in fragen), "mit Abweichungen")
